import{_ as t,o,c as n,a2 as r}from"./chunks/framework.Desnpdez.js";const u=JSON.parse('{"title":"Telekom Telecontext","description":"","frontmatter":{},"headers":[],"relativePath":"presets/telekom-telecontext.md","filePath":"presets/telekom-telecontext.md"}'),a={name:"presets/telekom-telecontext.md"};function s(l,e,i,c,d,g){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="telekom-telecontext" tabindex="-1">Telekom Telecontext <a class="header-anchor" href="#telekom-telecontext" aria-label="Permalink to &quot;Telekom Telecontext&quot;">​</a></h1><p><strong>Telekom Telecontext</strong> connects assistants to approved Telekom tools (for example Jira, GitLab, Confluence) through one MCP connection.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><ul><li>Your organisation must have <strong>Telekom Teleconsole</strong> access and your administrator must link accounts in the <strong>Telekom authorization portal</strong> when required.</li><li>In Teleconsole, finish <strong>Authorization services</strong> for <strong>every</strong> tool you plan to use—same scope you pick here.</li></ul><p>Tap <strong>Open authorization portal</strong> in the app if your admin shared that link.</p><h2 id="add-the-connection" tabindex="-1">Add the connection <a class="header-anchor" href="#add-the-connection" aria-label="Permalink to &quot;Add the connection&quot;">​</a></h2><ol><li><strong>Connections → Library</strong> → <strong>Telekom Telecontext</strong> → <strong>+</strong>.</li><li>In the configurator, pick <strong>tool categories</strong> or use <strong>All tools</strong> if your policy allows it.</li><li>Use <strong>Copy URL</strong> if an external system needs the generated MCP URL.</li><li><strong>Strip write tools</strong> is available when you want read-focused access—read the in-app <strong>How read-only works</strong> note.</li><li>Large selections show a <strong>tool count warning</strong>—over about fifty tools can slow assistants down; prefer the smallest useful set.</li></ol><p>Categories, <strong>Strip write tools</strong>, and <strong>Copy URL</strong> are all in the in-app configurator when you add the preset from the Library.</p><ol start="6"><li>Tap <strong>Add connection</strong>.</li></ol><h2 id="after-adding" tabindex="-1">After adding <a class="header-anchor" href="#after-adding" aria-label="Permalink to &quot;After adding&quot;">​</a></h2><ul><li>Enable the connection under <strong>My connections</strong> if it is not already on.</li><li>Turn the bridge <strong>on</strong> under <strong>Home</strong>, then <strong>Copy link</strong> or use <strong><a href="./../everyday/mbit-chat.html">MBIT Chat sync</a></strong>.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><strong><a href="./../everyday/connections.html">Connections</a></strong> — general Library and My connections flow.</li><li><strong><a href="./../help/troubleshooting.html">Troubleshooting</a></strong> — OAuth and connectivity.</li></ul>',13)])])}const p=t(a,[["render",s]]);export{u as __pageData,p as default};
